def _pin(data):return len(data),hashlib.sha256(data).hexdigest()

def transform_source(source,*,family):
    if type(source) is not bytes or type(family) is not str or family not in _RULES:
        raise ValueError('fixed B/C/E shipping source and explicit family required')
    before,after,spans,gaps,complement_pin=_RULES[family]
    if _pin(source)!=before:raise ValueError('exact pre-condition shipping source required')
    pieces=[];end=0
    for old_at,new_at,old,new in spans:
        if source[old_at:old_at+len(old)]!=old:raise ValueError('condition literal region differs')
        pieces.extend((source[end:old_at],new));end=old_at+len(old)
    result=b''.join(pieces)+source[end:];rest=[]
    for old_at,new_at,size,digest in gaps:
        a=source[old_at:old_at+size];b=result[new_at:new_at+size]
        if a!=b or _pin(a)!=(size,digest):raise ValueError('condition protected gap differs')
        rest.append(a)
    if _pin(b''.join(rest))!=complement_pin:raise ValueError('condition protected complement differs')
    inverse=[];end=0
    for old_at,new_at,old,new in spans:
        if result[new_at:new_at+len(new)]!=new:raise ValueError('condition output region differs')
        inverse.extend((result[end:new_at],old));end=new_at+len(new)
    if b''.join(inverse)+result[end:]!=source:raise ValueError('condition exact full inverse differs')
    if _pin(result)!=after:raise ValueError('fixed condition candidate differs')
    return result,dict(METADATA[family])
